import hashlib,json,pathlib,shutil,subprocess,sys,tempfile
package=pathlib.Path('products/sites/sqlite-statement-diagnostic/local')
output=pathlib.Path('products/services/sqlite-repair/original-fixture-controls/execution.json')
output.parent.mkdir(parents=True,exist_ok=True)
implementation=package/'diagnose.py'
base={'case_id':'fictional-inventory-total','seed_sql':'CREATE TABLE shelf(quantity INTEGER NOT NULL); INSERT INTO shelf VALUES (4),(7);','expected_rows':[[11]],'reproduce':True}
queries={'first_statement_only':'SELECT quantity FROM shelf ORDER BY quantity; SELECT SUM(quantity) FROM shelf;','corrected_single_statement':'SELECT SUM(quantity) FROM shelf;'}
results={}
with tempfile.TemporaryDirectory() as directory:
    work=pathlib.Path(directory)
    shutil.copyfile(implementation,work/'diagnose.py')
    for name,query in queries.items():
        case={**base,'query_sql':query}
        data=json.dumps(case,ensure_ascii=False).encode()
        (work/'case.json').write_bytes(data)
        command=[sys.executable,'diagnose.py','case.json']
        completed=subprocess.run(command,cwd=work,text=True,capture_output=True,timeout=15)
        results[name]={'case':case,'case_sha256':hashlib.sha256(data).hexdigest(),'command':command,'returncode':completed.returncode,'stdout':completed.stdout,'stderr':completed.stderr}
record={'scope':'Original synthetic inputs. Tool execution only. Inspect actual reports before asserting result differences, statement counts or cleanup.','implementation_sha256':hashlib.sha256(implementation.read_bytes()).hexdigest(),'results':results}
output.write_text(json.dumps(record,indent=2)+'\n',encoding='utf-8')
print(output.read_text(encoding='utf-8'))
